gYj(){return"\u062a\u0645\u062a \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0637\u0627\u0644\u0628."},
gafp(){return"\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0646\u0632\u0644 \u0639\u0644\u0649 \u0627\u0644\u062e\u0631\u064a\u0637\u0629"},
gahk(){return"\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062e\u0631\u064a\u0637\u0629 \u0644\u062a\u062d\u062f\u064a\u062f \u0645\u0646\u0632\u0644 \u0627\u0644\u0637\u0627\u0644\u0628."},
